package com.shubhasai.monkeymart

import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.performClick
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.shubhasai.monkeymart.ui.ShopScreen
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class ShopScreenTapTest {

    @get:Rule
    val composeRule = createComposeRule()

    @Test
    fun tappingProductInvokesCallbackQuicklyWithoutBlockingMainThread() {
        val clicked = mutableListOf<Int>()
        composeRule.setContent { ShopScreen(onProductClick = { clicked.add(it) }) }

        composeRule.waitUntil(timeoutMillis = 5_000) {
            composeRule.onAllNodesWithTagCount("product_1") > 0
        }

        val start = System.nanoTime()
        composeRule.onNodeWithTag("product_1").performClick()
        composeRule.waitUntil(timeoutMillis = 1_000) { clicked.isNotEmpty() }
        val elapsedMs = (System.nanoTime() - start) / 1_000_000

        assertEquals(listOf(1), clicked)
        assertTrue("Tap took ${elapsedMs}ms; main thread was blocked", elapsedMs < 1_500)
    }

    private fun androidx.compose.ui.test.junit4.ComposeContentTestRule.onAllNodesWithTagCount(
        tag: String,
    ): Int = onAllNodes(androidx.compose.ui.test.hasTestTag(tag)).fetchSemanticsNodes().size
}
